@page "/"
@inject NavigationManager Navigation

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="container mt-4">
    <h1>Welcome to ShipmentTracker</h1>
    <p class="lead">Your logistics management solution for tracking shipments from origin to destination.</p>

    <div class="card mt-4">
        <div class="card-body">
            <h5 class="card-title">Track a Shipment</h5>
            <p class="card-text">Enter your tracking number to see the current status of your shipment.</p>
            <div class="input-group">
                <input type="text" class="form-control" placeholder="e.g. SHP-001-2026" @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
            </div>
        </div>
    </div>

    <AuthorizeView>
        <Authorized>
            <div class="mt-4">
                <a href="shipments" class="btn btn-outline-primary">Go to Shipments Dashboard</a>
            </div>
        </Authorized>
    </AuthorizeView>
</div>

@code {
    private string trackingNumber = string.Empty;

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            Navigation.NavigateTo($"/track?number={Uri.EscapeDataString(trackingNumber)}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            TrackShipment();
    }
}

