@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments Dashboard</PageTitle>

<h1>Shipments Dashboard</h1>

@if (loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <div class="mb-3">
        <label class="form-label">Filter by Status:</label>
        <select class="form-select w-auto d-inline-block ms-2" @bind="statusFilter">
            <option value="">All</option>
            <option value="Pending">Pending</option>
            <option value="PickedUp">Picked Up</option>
            <option value="InTransit">In Transit</option>
            <option value="OutForDelivery">Out For Delivery</option>
            <option value="Delivered">Delivered</option>
            <option value="Cancelled">Cancelled</option>
        </select>
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking Number</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Update Status</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@FormatStatus(shipment.Status)</span></td>
                    <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                    <td>
                        <div class="d-flex gap-2">
                            <select class="form-select form-select-sm w-auto" @bind="statusUpdates[shipment.Id]">
                                <option value="Pending">Pending</option>
                                <option value="PickedUp">Picked Up</option>
                                <option value="InTransit">In Transit</option>
                                <option value="OutForDelivery">Out For Delivery</option>
                                <option value="Delivered">Delivered</option>
                                <option value="Cancelled">Cancelled</option>
                            </select>
                            <button class="btn btn-sm btn-primary" @onclick="() => UpdateStatus(shipment)">Update</button>
                        </div>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string statusFilter = "";
    private Dictionary<int, string> statusUpdates = new();

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrEmpty(statusFilter)
            ? shipments
            : shipments.Where(s => s.Status == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
        foreach (var s in shipments)
            statusUpdates[s.Id] = s.Status;
        loading = false;
    }

    private async Task UpdateStatus(ShipmentDto shipment)
    {
        if (statusUpdates.TryGetValue(shipment.Id, out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            if (updated is not null)
            {
                var idx = shipments.FindIndex(s => s.Id == shipment.Id);
                if (idx >= 0)
                    shipments[idx] = updated;
            }
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-warning text-dark",
        "PickedUp" => "bg-info text-dark",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-info",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out For Delivery",
        _ => status
    };
}

@page "/track"
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="input-group mb-4" style="max-width: 500px;">
    <input type="text" class="form-control" placeholder="Enter tracking number" @bind="trackingInput" @bind:event="oninput" @onkeydown="HandleKeyDown" />
    <button class="btn btn-primary" @onclick="Search">Track</button>
</div>

@if (searching)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Searching...</span>
        </div>
    </div>
}
else if (notFound)
{
    <div class="alert alert-warning">Shipment not found. Please check your tracking number and try again.</div>
}
else if (shipment is not null)
{
    <div class="card" style="max-width: 600px;">
        <div class="card-body">
            <h4 class="card-title">@shipment.TrackingNumber</h4>
            <div class="my-3">
                <span class="badge fs-5 @GetStatusBadgeClass(shipment.Status)">@FormatStatus(shipment.Status)</span>
            </div>
            <dl class="row mb-0">
                <dt class="col-sm-5">Origin</dt>
                <dd class="col-sm-7">@shipment.Origin</dd>
                <dt class="col-sm-5">Destination</dt>
                <dd class="col-sm-7">@shipment.Destination</dd>
                <dt class="col-sm-5">Estimated Delivery</dt>
                <dd class="col-sm-7">@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</dd>
                @if (shipment.ActualDelivery is not null)
                {
                    <dt class="col-sm-5">Actual Delivery</dt>
                    <dd class="col-sm-7">@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
                }
                <dt class="col-sm-5">Description</dt>
                <dd class="col-sm-7">@shipment.Description</dd>
            </dl>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery(Name = "number")]
    public string? Number { get; set; }

    private string trackingInput = string.Empty;
    private ShipmentDto? shipment;
    private bool notFound;
    private bool searching;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(Number))
        {
            trackingInput = Number;
            await Search();
        }
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingInput))
            return;

        searching = true;
        notFound = false;
        shipment = null;

        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingInput.Trim());
        notFound = shipment is null;
        searching = false;
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            InvokeAsync(Search);
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-warning text-dark",
        "PickedUp" => "bg-info text-dark",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-info",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out For Delivery",
        _ => status
    };
}

