@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string statusFilter = "";
    private Dictionary<int, string> statusUpdates = new();

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrEmpty(statusFilter)
            ? shipments
            : shipments.Where(s => s.Status == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
        foreach (var s in shipments)
            statusUpdates[s.Id] = s.Status;
        loading = false;
    }

    private async Task UpdateStatus(ShipmentDto shipment)
    {
        if (statusUpdates.TryGetValue(shipment.Id, out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            if (updated is not null)
            {
                var idx = shipments.FindIndex(s => s.Id == shipment.Id);
                if (idx >= 0)
                    shipments[idx] = updated;
            }
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-warning text-dark",
        "PickedUp" => "bg-info text-dark",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-info",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out For Delivery",
        _ => status
    };
}

