    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingInput))
            return;

        searching = true;
        notFound = false;
        shipment = null;

        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingInput.Trim());
        notFound = shipment is null;
        searching = false;
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            InvokeAsync(Search);
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-warning text-dark",
        "PickedUp" => "bg-info text-dark",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-info",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out For Delivery",
        _ => status
    };
}

