1. using Microsoft.EntityFrameworkCore;
2. using ShipmentTracker.Client.Models;
3. using ShipmentTracker.Client.Services;
4. using ShipmentTracker.Data;
5. 
6. namespace ShipmentTracker.Services;
7. 
8. public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
9. {
10.     public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
11.     {
12.         return await db.Shipments
13.             .Select(s => MapToDto(s))
14.             .ToListAsync();
15.     }
16. 
17.     public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
18.     {
19.         var shipment = await db.Shipments
20.             .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
21.         return shipment is null ? null : MapToDto(shipment);
22.     }
23. 
24.     public async Task<ShipmentDto?> UpdateShipmentStatusAsync(int id, string status)
25.     {
26.         var shipment = await db.Shipments.FindAsync(id);
27.         if (shipment is null)
28.             return null;
29. 
30.         if (!Enum.TryParse<ShipmentStatus>(status, true, out var parsedStatus))
31.             return null;
32. 
33.         shipment.Status = parsedStatus;
34.         if (parsedStatus == ShipmentStatus.Delivered)
35.             shipment.ActualDelivery = DateTime.UtcNow;
36. 
37.         await db.SaveChangesAsync();
38.         return MapToDto(shipment);
